n-5 justify-start order-1 md:order-none" data-qa-id="ProductDescription-left-column"><div class="grid grid-cols-12 w-full component [&amp;.component_&amp;]:p-0 h-full"><div class="col-span-12"><div id="Details" class="w-full flex flex-col gap-4 max-w-[var(--breakpoint-container-max-width)] mx-auto text-black"><div class="flex flex-col gap-2"><h2 class="heading-md text-action-color-secondary !normal-case">Details</h2></div></div></div></div></div><div class="col-span-12 h-full flex flex-col overflow-visible md:col-span-7 justify-start order-2 md:order-none" data-qa-id="ProductDescription-right-column"><div class="grid grid-cols-12 w-full component [&amp;.component_&amp;]:p-0 h-full"><div class="col-span-12"><div id="What Does Our Brake Service Include?" class="w-full flex flex-col gap-4 max-w-[var(--breakpoint-container-max-width)] mx-auto text-black"><div class="flex flex-col gap-2"><h2 class="heading-md text-action-color-secondary !normal-case">What Does Our Brake Service Include?</h2><hr aria-hidden="true" class="Divider-module-scss-module__jL2KVW__divider Divider-module-scss-module__jL2KVW__divider--light !my-4 sm:!my-6"></div><div class=" last:mb-0"><h4 class="subtitle-lg text-action-color-secondary mb-4"><span class="!normal-case subtitle-lg">What Does Our Brake Service Include?</span></h4> <p class="paragraph-md text-action-color-secondary !normal-case">Our specially trained brake specialists will inspect, repair, and if necessary, replace your brake system to ensure it's working efficiently and effectively. Our brake service and repair includes:</p> <ul class="paragraph-md text-action-color-secondary list-disc pl-6 space-y-1 !normal-case mb-2"> <li class="paragraph-md text-action-color-secondary m-0 mb-2 !normal-case">Replacing your worn brake pads and/or brake shoes</li> <li class="paragraph-md text-action-color-secondary m-0 mb-2 !normal-case">Resurfacing your brake rotors or drums</li> <li class="paragraph-md text-action-color-secondary m-0 mb-2 !normal-case">Replacing your brake fluid as needed</li> </ul> <h4 class="subtitle-lg text-action-color-secondary mb-4"><span class="!normal-case subtitle-lg">The Importance of Scheduling a Brake Service</span></h4> <p class="paragraph-md text-action-color-secondary !normal-case">Brakes are made of materials and components that wear down over time and they need to be inspected, repaired or replaced on a routine basis.</p> <p class="paragraph-md text-action-color-secondary !normal-case">When brake inspections and maintenance are overlooked, it can lead to costlier repairs and replacements, as well as a dangerous inability to stop your vehicle.</p> <h4 class="subtitle-lg text-action-color-secondary mb-4"><span class="!normal-case subtitle-lg">How Often Do You Need New Brakes?</span></h4> <p class="paragraph-md text-action-color-secondary !normal-case">We recommend having your brakes checked every 12 months or 15,000 miles. It’s always a good idea to check your owner’s manual for your vehicle manufacturer’s recommendation.</p></div></div></div></div></div></div></div></div></div></div></section></div></div></div></div><div id="product-faq-4" class="component xxl:mb-desktop-spacing-margin-bottom-xl md:mb-desktop-spacing-padding-lg sm:mb-tablet-spacing-margin-bottom-lg mb-mobile-spacing-margin-bottom-xl component [&amp;:has(.empty-component)]:!mb-0 component !mb-mobile-spacing-margin-bottom-md sm:!mb-tablet-spacing-margin-bottom-md lg:!mb-desktop-spacing-margin-bottom-md"><div class="grid grid-cols-12 w-full component [&amp;.component_&amp;]:p-0 mx-auto max-w-screen-xxl px-4 sm:px-6 md:px-8 lg:px-12 xl:px-16" data-qa-id="dynamic-component-container"><div class="col-span-12"><div class="max-w-[var(--breakpoint-container-max-width)] mx-auto dynamic-component-wrapper text-type-standard"><section id="productFaq" class="scroll-mt-20" data-qa-id="ProductFaq" data-theme="light"><div class="grid grid-cols-12 w-full h-full component [&amp;.component_&amp;]:p-0 px-4 sm:px-6 md:px-8 lg:px-12 